import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { sendChatMessage } from '../services/api';

export default function Chat() {
  const navigate = useNavigate();
  const [message, setMessage] = useState('');
  const [conversation, setConversation] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await sendChatMessage(message);
      setConversation((current) => [
        ...current,
        { role: 'user', text: response.message || message || 'No data available' },
        { role: 'bot', text: response.response || 'No data available' },
      ]);
      setMessage('');
    } catch (submitError) {
      if (submitError.message === 'Missing authentication token') {
        navigate('/login');
        return;
      }
      setError(submitError.message || 'Failed to fetch data');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <div style={styles.headerRow}>
          <h1 style={styles.title}>Health Chatbot</h1>
          <button type="button" style={styles.secondaryButton} onClick={() => navigate('/dashboard')}>
            Back to Dashboard
          </button>
        </div>

        <div style={styles.chatWindow}>
          {conversation.length === 0 ? <p style={styles.placeholder}>No data available</p> : null}
          {conversation.map((entry, index) => (
            <div
              key={`${entry.role}-${index}`}
              style={entry.role === 'user' ? styles.userBubble : styles.botBubble}
            >
              {entry.text}
            </div>
          ))}
        </div>

        <form onSubmit={handleSubmit} style={styles.form}>
          <input
            type="text"
            placeholder="Ask a health question"
            value={message}
            onChange={(event) => setMessage(event.target.value)}
            style={styles.input}
          />
          <button type="submit" style={styles.submitButton} disabled={loading}>
            Send
          </button>
        </form>

        {loading ? <p style={styles.message}>Loading...</p> : null}
        {error ? <p style={styles.error}>{error}</p> : null}
      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: '100vh',
    background: '#eff8f2',
    padding: '32px 20px',
    fontFamily: 'Segoe UI, sans-serif',
  },
  card: {
    maxWidth: '820px',
    margin: '0 auto',
    background: '#ffffff',
    borderRadius: '24px',
    padding: '30px',
    boxShadow: '0 16px 40px rgba(32, 84, 61, 0.12)',
  },
  headerRow: {
    display: 'flex',
    justifyContent: 'space-between',
    gap: '16px',
    alignItems: 'center',
    flexWrap: 'wrap',
    marginBottom: '24px',
  },
  title: {
    margin: 0,
    color: '#1f4d3b',
  },
  secondaryButton: {
    padding: '12px 16px',
    borderRadius: '12px',
    border: 'none',
    background: '#ebf4ee',
    color: '#1f4d3b',
    cursor: 'pointer',
    fontWeight: 700,
  },
  chatWindow: {
    minHeight: '320px',
    maxHeight: '460px',
    overflowY: 'auto',
    padding: '18px',
    background: '#f7fbf8',
    border: '1px solid #d9ebdf',
    borderRadius: '18px',
    marginBottom: '18px',
    display: 'grid',
    gap: '12px',
  },
  placeholder: {
    margin: 0,
    color: '#799283',
  },
  userBubble: {
    justifySelf: 'end',
    maxWidth: '75%',
    background: '#1f7a55',
    color: '#ffffff',
    padding: '12px 14px',
    borderRadius: '16px 16px 4px 16px',
  },
  botBubble: {
    justifySelf: 'start',
    maxWidth: '75%',
    background: '#e7f4ec',
    color: '#244a3b',
    padding: '12px 14px',
    borderRadius: '16px 16px 16px 4px',
  },
  form: {
    display: 'grid',
    gridTemplateColumns: '1fr auto',
    gap: '12px',
  },
  input: {
    padding: '14px 16px',
    borderRadius: '12px',
    border: '1px solid #caded3',
    fontSize: '15px',
  },
  submitButton: {
    padding: '14px 18px',
    borderRadius: '12px',
    border: 'none',
    background: '#1f7a55',
    color: '#ffffff',
    cursor: 'pointer',
    fontWeight: 700,
  },
  message: {
    marginTop: '16px',
    color: '#245f49',
  },
  error: {
    marginTop: '16px',
    color: '#c0392b',
  },
};
